python3 -c "
import xml.etree.ElementTree as ET
import glob, os, re

files = glob.glob('/tmp/*.xml')
for f in files:
    if any(k in f for k in ['coindesk', 'cointelegraph', 'decrypt', 'beincrypto', 'cryptoslate', 'cryptofox', 'google_news']):
        if '_feed' in f or 'feed_' in f:
            continue
        print('===', os.path.basename(f), '===')
        try:
            tree = ET.parse(f)
            root = tree.getroot()
            count = 0
            for item in root.findall('.//item'):
                title = item.find('title')
                pub = item.find('pubDate')
                link = item.find('link')
                t_str = title.text if title is not None else ''
                p_str = pub.text if pub is not None else ''
                l_str = link.text if link is not None else ''
                # check if pubdate is today/yesterday (May 25 or May 26 2026)
                if '2026' in p_str and ('May' in p_str or '05' in p_str):
                    if '25' in p_str or '26' in p_str:
                        print(f' - [{p_str}] {t_str} ({l_str})')
                        count += 1
                        if count > 15:
                            break
        except Exception as e:
            print('Error:', e)
"
